// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(address addr, string memory desc) internal {
        bool revert1 = false;
        try c.newEmergencyOracle(desc) {} catch { revert1 = true; }
        assertTrue(revert1 == true);
    }

    function testFuzz_test(address addr, string memory desc) public {
        vm.assume(addr.code.length == 0 && uint160(addr) > 0xffff && addr != address(this) && addr != address(c) && addr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && addr != 0x000000000000000000636F6e736F6c652e6c6f67 && addr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && addr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _test(addr, desc);
    }
}
